Here is the commit message:
net: lan966x: Fix duplicate check in frame extraction

The blamed commit generates the following smatch static checker warning:

 drivers/net/ethernet/microchip/lan966x/lan966x_main.c:515 lan966x_xtr_irq_handler()
         warn: duplicate check 'sz < 0' (previous on line 502)

This patch fixes this issue removing the duplicate check 'sz < 0'

Fixes: d28d6d2e37d10d ("net: lan966x: add port module support")
Signed-off-by: Horatiu Vultur <horatiu.vultur@microchip.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The root cause of the bug is a redundant check for the condition `sz < 0` within the `lan966x_xtr_irq_handler` function. This check was already performed earlier in the function, leading to a static checker warning about the duplicate condition. The presence of this unnecessary check can create confusion and potential maintenance issues in the code.

Here is the patch:

 static irqreturn_t lan966x_xtr_irq_handler(int irq, void *args)
 {
 	struct lan966x *lan966x = args;
 	int i, grp = 0, err = 0;

 	if (!(lan_rd(lan966x, QS_XTR_DATA_PRESENT) & BIT(grp)))
 		return IRQ_NONE;

 	do {
 		struct net_device *dev;
 		struct sk_buff *skb;
 		int sz = 0, buf_len;
 		u64 src_port, len;
 		u32 ifh[IFH_LEN];
 		u32 *buf;
 		u32 val;

 		for (i = 0; i < IFH_LEN; i++) {
 			err = lan966x_rx_frame_word(lan966x, grp, &ifh[i]);
 			if (err != 4)
 				goto recover;
 		}

 		err = 0;

 		lan966x_ifh_get_src_port(ifh, &src_port);
 		lan966x_ifh_get_len(ifh, &len);

 		WARN_ON(src_port >= lan966x->num_phys_ports);

 		dev = lan966x->ports[src_port]->dev;
 		skb = netdev_alloc_skb(dev, len);
 		if (unlikely(!skb)) {
 			netdev_err(dev, "Unable to allocate sk_buff\n");
 			err = -ENOMEM;
 			break;
 		}
 		buf_len = len - ETH_FCS_LEN;
 		buf = (u32 *)skb_put(skb, buf_len);

 		len = 0;
 		do {
 			sz = lan966x_rx_frame_word(lan966x, grp, &val);
 			if (sz < 0) {
 				kfree_skb(skb);
 				goto recover;
 			}

 			*buf++ = val;
 			len += sz;
 		} while (len < buf_len);

 		/* Read the FCS */
 		sz = lan966x_rx_frame_word(lan966x, grp, &val);
 		if (sz < 0) {
 			kfree_skb(skb);
 			goto recover;
 		}

 		/* Update the statistics if part of the FCS was read before */
 		len -= ETH_FCS_LEN - sz;

 		if (unlikely(dev->features & NETIF_F_RXFCS)) {
 			buf = (u32 *)skb_put(skb, ETH_FCS_LEN);
 			*buf = val;
 		}

-		if (sz < 0) {
-			err = sz;
-			break;
-		}
-
 		skb->protocol = eth_type_trans(skb, dev);

 		netif_rx_ni(skb);
 		dev->stats.rx_bytes += len;
 		dev->stats.rx_packets++;

 recover:
 		if (sz < 0 || err)
 			lan_rd(lan966x, QS_XTR_RD(grp));

 	} while (lan_rd(lan966x, QS_XTR_DATA_PRESENT) & BIT(grp));

 	return IRQ_HANDLED;
 }



